impl Solution{pub fn restore_ip_addresses(s:String)->Vec<String>{fn f(s:&str,p:usize,part:usize,v:&mut Vec<String>,o:&mut Vec<String>){if part==4{if p==s.len(){o.push(v.join("."));}return}for l in 1..=3{if p+l>s.len(){break}if l>1&&&s[p..p+1]=="0"{break}let x=&s[p..p+l];if x.parse::<i32>().unwrap()>255{break}v.push(x.to_string());f(s,p+l,part+1,v,o);v.pop();}}let mut o=vec![];f(&s,0,0,&mut vec![],&mut o);o}}
